    return value != "" and value is not None


def _guard_true(guard: str | None, record: dict[str, Any]) -> bool:
    if guard is None:
        return True

    if guard == "OWNER_UID <> ''":
        return _nonempty(_value(record, "OWNER_UID"))

    if guard == "ESC_FLG <> 'Y'":
        return _value(record, "ESC_FLG") != "Y"

    if guard == "RES_DT <> '00000000'":
        return _value(record, "RES_DT") != "00000000"

    return False


