            and _guard_true(transition["guard"], updated_record)
        ):
            audits: list[str] = []
            notifies: list[str] = []
            resulting_state = transition["to"]

            for action in transition["actions"]:
                if action[0] == "set":
                    _, field, value = action
                    updated_record[field] = _evaluate_value(value, updated_record)
                elif action[0] == "audit":
                    audits.append(action[1])
                elif action[0] == "notify":
                    notifies.append(action[1])

            return {
                "state": resulting_state,
                "record": updated_record,
                "audits": audits,
                "notifies": notifies,
                "matched": True,
            }

    return {
        "state": state,
        "record": updated_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
